// Every #[tauri::command] must be listed here: tauri-plugin generates an
// allow-<command> permission for each (permissions/autogenerated/).
const COMMANDS: &[&str] = &["ping", "probe_source", "start_convert", "start_merge", "cancel_job", "estimate_sizes", "set_preview_files", "engine_status", "engine_set_path", "engine_latest", "engine_install", "engine_cancel", "engine_remove", "engine_prompt", "engine_set_prompted"];

fn main() {
  tauri_plugin::Builder::new(COMMANDS).build();
}
